def biseccion(f, a, b, tol=1e-8, max_iter=50):
    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol:
            print(f"Convergió en iter {k}: c = {c}")
            break
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    else:
        print("No convergió en max_iter")

f = lambda x: x**3 - x - 2
biseccion(f, 1, 2)

